import json

# Fix the logic
grid = [[9]*22 for _ in range(7)]
grid[0][17:22] = [1]*5
grid[6][0:5] = [1]*5

threes = [(2,2), (3,0), (3,3), (4,1), (4,4)]

for r, c in threes:
    grid[r][c] = 4

    # Simpler approach: expand toward nearest corner center
    top_right_center = (0, 20)  # approximate center of top-right region
    bottom_left_center = (6, 2)  # approximate center of bottom-left region

    dist_tr = abs(r - top_right_center[0]) + abs(c - top_right_center[1])
    dist_bl = abs(r - bottom_left_center[0]) + abs(c - bottom_left_center[1])

    if dist_tr < dist_bl:
        # Expand right/up toward top-right
        for dr in [-1, 0]:
            for dc in [0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 7 and 0 <= nc < 22:
                    if grid[nr][nc] == 9:
                        grid[nr][nc] = 3
                    else:
                        break
    else:
        # Expand left/down toward bottom-left  
        for dr in [0, 1]:
            for dc in [-1, 0]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 7 and 0 <= nc < 22:
                    if grid[nr][nc] == 9:
                        grid[nr][nc] = 3
                    else:
                        break

print("Prediction:")
for row in grid:
    print(' '.join(map(str, row)))

result = json.dumps({"action": "submit", "grid": grid})
print(result)

